import{_ as t,o as a,c as l,ai as i}from"./chunks/framework.ampVZV4B.js";const u=JSON.parse('{"title":"Context & Rules","description":"","frontmatter":{},"headers":[],"relativePath":"ai/dev/coding/context-and-rules.md","filePath":"ai/dev/coding/context-and-rules.md"}'),o={name:"ai/dev/coding/context-and-rules.md"};function r(s,e,n,p,d,c){return a(),l("div",null,[...e[0]||(e[0]=[i(`<h1 id="context-rules" tabindex="-1">Context &amp; Rules <a class="header-anchor" href="#context-rules" aria-label="Permalink to “Context &amp; Rules”">​</a></h1><blockquote><p>一页讲清楚：Context 是项目事实，Rules 是长期约束。够用即可，不建复杂规范体系。</p></blockquote><p>本页只解释这两个词，以及它们和 Spec、Prompt、AGENTS 的边界。<br> 阶段顺序见 <a href="/my-vitepress-site/ai/dev/coding/cursor-workflow.html">AI Coding 工作流</a>。文件怎么放，只看 <a href="/my-vitepress-site/ai/dev/coding/project-landing-kit.html">项目落地包</a>。</p><h3 id="什么时候用" tabindex="-1">什么时候用？ <a class="header-anchor" href="#什么时候用" aria-label="Permalink to “什么时候用？”">​</a></h3><ul><li>AI 不理解项目</li><li>AI 总改错位置</li><li>AI 不遵守这个项目里已经有的规矩</li><li>每次都要在聊天里重复解释项目背景</li></ul><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h3><blockquote><p>不是给 AI 塞更多信息，而是给足够且必要的事实，加上不能破的约束。</p></blockquote><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Context = 项目现在是什么</span></span>
<span class="line"><span>Rules   = 这个项目里所有任务都必须遵守什么</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>没有 Context，AI 只能猜。<br> 没有 Rules，AI 容易用「它喜欢的写法」生成你维护不了的代码。</p><hr><h2 id="context-是什么" tabindex="-1">Context 是什么 <a class="header-anchor" href="#context-是什么" aria-label="Permalink to “Context 是什么”">​</a></h2><p>Context 描述<strong>项目事实</strong>。不是这一次要改什么，也不是你希望项目变成什么样。</p><p>例如：</p><ul><li>项目结构、做什么、给谁用</li><li>技术栈</li><li>模块关系</li><li>已有接口、已有数据库</li><li>已经成立的业务约束</li><li>当前系统的真实行为</li></ul><blockquote><p>Context 应该来自真实项目，而不是 AI 自己猜出来的理想状态。</p></blockquote><p>用事实，不写愿景口号。缺了就写「未知 / 待确认」，不要让 AI 编。与手头工作相关的事实优先，不要一上来贴整仓，也不要指望 AI 自己读懂没写下来的东西。</p><p>项目事实放在 <code>docs/ai-context/</code>。本页不提供文件模板。</p><hr><h2 id="rules-是什么" tabindex="-1">Rules 是什么 <a class="header-anchor" href="#rules-是什么" aria-label="Permalink to “Rules 是什么”">​</a></h2><p>Rules 是<strong>长期约束</strong>：这个项目里每一次任务都要遵守，不是只约束今天这一刀。</p><p>例如：</p><ul><li>哪些模块不能互相依赖</li><li>哪些目录不能随便改</li><li>不擅自改表结构，不擅自改已发布的 API</li><li>不确定就停下来确认</li><li>不擅自扩大修改范围</li></ul><p>「只能改哪些文件」是 Rules 里的一种约束，不是另一套写法，也不必每次抄进对话。</p><blockquote><p>Rules 来自项目真实习惯和明确约束，不是为了看起来专业编出来的规范。</p></blockquote><p>具体条文只维护在规则文件里。本页不列清单，也不维护第二份模板。</p><hr><h2 id="为什么要分开" tabindex="-1">为什么要分开 <a class="header-anchor" href="#为什么要分开" aria-label="Permalink to “为什么要分开”">​</a></h2><p>Context 会变：查清一条调用链、多确认一个事实，就改 Context。<br> 规矩没变，就不要写进 Context，也不要为了一次任务去改 Rules。</p><p>系统<strong>现在就是这样</strong>，写 Context。<br><strong>不许打破它</strong>，写 Rules。</p><p>一次任务的「做什么、验收、不做」两边都不写。那是 Spec。</p><hr><h2 id="和-spec、prompt-怎么分" tabindex="-1">和 Spec、Prompt 怎么分 <a class="header-anchor" href="#和-spec、prompt-怎么分" aria-label="Permalink to “和 Spec、Prompt 怎么分”">​</a></h2><table tabindex="0"><thead><tr><th>东西</th><th>回答什么</th></tr></thead><tbody><tr><td>Context</td><td>项目现在是什么</td></tr><tr><td>Rules</td><td>项目里应该遵守什么</td></tr><tr><td>Spec</td><td>这一次具体做什么</td></tr><tr><td>Prompt</td><td>这一轮让 AI 怎么做</td></tr></tbody></table><ul><li>Context 是事实</li><li>Rules 是长期约束</li><li>Spec 是当前任务的冻结约定</li><li>Prompt 是一次交互指令</li></ul><blockquote><p>Prompt 用完可以扔；Spec 应该留下。</p></blockquote><p>Prompt 不能代替 Spec。Spec 放在流程的哪一步、确认时看哪几件事，见 <a href="/my-vitepress-site/ai/dev/coding/cursor-workflow.html">AI Coding 工作流</a>。本页不讲 Spec 怎么写。</p><p>Context 和 Rules 应尽量沉淀在项目文件里，让 AI 靠这些文件获得稳定信息，而不是每次在聊天窗口里重新粘贴。</p><hr><h2 id="agents-是什么" tabindex="-1">AGENTS 是什么 <a class="header-anchor" href="#agents-是什么" aria-label="Permalink to “AGENTS 是什么”">​</a></h2><p><code>AGENTS.md</code> 是项目卡，给 AI 的入口说明。它不是 Rules，也不是 Spec。</p><p>它只帮 AI 很快知道：这是什么项目、主要模块在哪、常用命令是什么、Context / Rules / Spec 放在哪、有哪些基本注意事项。</p><ul><li>不承载一次任务的 Spec</li><li>不写成几百行百科</li><li>具体 Rules 在规则文件</li><li>项目事实在 <code>docs/ai-context/</code></li><li>当前任务的 Spec 在 <code>docs/ai-context/specs/</code>，有这次任务再写，不预建空目录</li></ul><p>模板只在 <a href="/my-vitepress-site/ai/dev/coding/project-landing-kit.html">项目落地包</a>。</p><hr><h2 id="新项目和老项目" tabindex="-1">新项目和老项目 <a class="header-anchor" href="#新项目和老项目" aria-label="Permalink to “新项目和老项目”">​</a></h2><p>Context 的定义相同，来源不同。这里不讲操作步骤。</p><p><strong>新项目</strong>更多来自已经确定的事实：架构、技术选型、模块划分、数据和接口、项目目标。人写下来的是已知事实，不是愿景。</p><p><strong>老项目</strong>更多来自已经存在的东西：代码、数据库、配置、接口、调用链、实际运行行为。</p><blockquote><p>AI 可以负责扫描和整理，但不能把扫描出来的猜测直接当成事实。</p></blockquote><p>人确认之后，才写进 Context。</p><hr><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to “一句话”">​</a></h2><blockquote><p><strong>Context 解决「AI 不知道项目是什么」；Rules 解决「AI 知道项目是什么，但不知道哪些事情不能随便做」；Spec 再解决「这一次到底做什么」。</strong></p></blockquote><p>不必一上来建企业级规范库。先够用，再在真实任务里补事实和约束。</p>`,54)])])}const b=t(o,[["render",r]]);export{u as __pageData,b as default};
